module debt_resolver (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] debtor_0, debtor_1, debtor_2, debtor_3, debtor_4, debtor_5, debtor_6, debtor_7,\n    input [7:0] debt_0, debt_1, debt_2, debt_3, debt_4, debt_5, debt_6, debt_7,\n    output reg [15:0] total_money,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] FIND_NODE    = 3'd1;\n    localparam [2:0] TRAVERSE     = 3'd2;\n    localparam [2:0] CALC_MIN     = 3'd3;\n    localparam [2:0] UPDATE_TOTAL = 3'd4;\n    localparam [2:0] COMPLETE     = 3'd5;\n    \n    reg [2:0] state, next_state;\n    \n    // Node management\n    reg [2:0] node_index;\n    reg [2:0] current_node;\n    reg [2:0] start_node;\n    reg [7:0] visited;\n    reg [15:0] min_debt;\n    reg [2:0] traverse_steps;\n    \n    // Cycle prevention\n    reg [7:0] cycle_counter;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // Debt array\n    wire [7:0] debtors [0:7];\n    wire [7:0] debts [0:7];\n    assign debtors[0] = debtor_0;\n    assign debtors[1] = debtor_1;\n    assign debtors[2] = debtor_2;\n    assign debtors[3] = debtor_3;\n    assign debtors[4] = debtor_4;\n    assign debtors[5] = debtor_5;\n    assign debtors[6] = debtor_6;\n    assign debtors[7] = debtor_7;\n    \n    assign debts[0] = debt_0;\n    assign debts[1] = debt_1;\n    assign debts[2] = debt_2;\n    assign debts[3] = debt_3;\n    assign debts[4] = debt_4;\n    assign debts[5] = debt_5;\n    assign debts[6] = debt_6;\n    assign debts[7] = debt_7;\n    \n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            total_money <= 16'd0;\n            done <= 1'b0;\n            node_index <= 3'd0;\n            visited <= 8'd0;\n            min_debt <= 16'hFFFF;\n            traverse_steps <= 3'd0;\n            cycle_counter <= 8'd0;\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        total_money <= 16'd0;\n                        done <= 1'b0;\n                        visited <= 8'd0;\n                        node_index <= 3'd0;\n                        cycle_counter <= 8'd0;\n                    end\n                end\n                \n                FIND_NODE: begin\n                    if (node_index < 3'd7) begin\n                        node_index <= node_index + 3'd1;\n                    end\n                end\n                \n                TRAVERSE: begin\n                    traverse_steps <= traverse_steps + 3'd1;\n                    current_node <= debtors[current_node];\n                    \n                    // Track minimum debt\n                    if (debts[current_node] < min_debt) begin\n                        min_debt <= debts[current_node];\n                    end\n                end\n                \n                CALC_MIN: begin\n                    // Update visited for all nodes in cycle\n                    visited[current_node] <= 1'b1;\n                    if (current_node != start_node) begin\n                        current_node <= debtors[current_node];\n                    end\n                end\n                \n                UPDATE_TOTAL: begin\n                    total_money <= total_money + min_debt;\n                    min_debt <= 16'hFFFF;\n                    traverse_steps <= 3'd0;\n                end\n                \n                COMPLETE: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        \n        case (state)\n            IDLE: begin\n                if (start) next_state = FIND_NODE;\n            end\n            \n            FIND_NODE: begin\n                if (cycle_counter >= MAX_CYCLES) next_state = COMPLETE;\n                else if (node_index >= 3'd7 && visited == 8'hFF) next_state = COMPLETE;\n                else if (visited[node_index] == 1'b0 && debtors[node_index] < 8'd8) begin\n                    next_state = TRAVERSE;\n                end else if (node_index < 3'd7) begin\n                    next_state = FIND_NODE;\n                end else begin\n                    next_state = COMPLETE;\n                end\n            end\n            \n            TRAVERSE: begin\n                if (cycle_counter >= MAX_CYCLES) next_state = COMPLETE;\n                else if (current_node == start_node && traverse_steps > 0) next_state = CALC_MIN;\n                else if (traverse_steps >= 3'd7) next_state = CALC_MIN;\n                else if (visited[current_node] || debtors[current_node] >= 8'd8) next_state = FIND_NODE;\n            end\n            \n            CALC_MIN: begin\n                if (current_node == start_node) next_state = UPDATE_TOTAL;\n            end\n            \n            UPDATE_TOTAL: begin\n                next_state = FIND_NODE;\n            end\n            \n            COMPLETE: begin\n                next_state = IDLE;\n            end\n            \n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // Start node and current node initialization\n    always @(*) begin\n        if (state == FIND_NODE && next_state == TRAVERSE) begin\n            start_node = node_index;\n            current_node = node_index;\n        end\n    end\n    \nendmodule